function x($v){return htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8');}
function getv($arr,$key,$default=''){return trim((string)($arr[$key]??$default));}
function runText($text,$bold=false,$size=22){$text=(string)$text; $parts=explode("\n",$text);$out='';foreach($parts as $i=>$part){if($i)$out.='<w:r><w:br/></w:r>';$out.='<w:r><w:rPr>'.($bold?'<w:b/>':'').'<w:sz w:val="'.$size.'"/><w:szCs w:val="'.$size.'"/></w:rPr><w:t xml:space="preserve">'.x($part).'</w:t></w:r>'; }return $out;}
function para($text='',$opts=[]){$align=$opts['align']??'both';$before=$opts['before']??0;$after=$opts['after']??100;$size=$opts['size']??22;$bold=$opts['bold']??false;$style=$opts['style']??'';$ppr='<w:pPr>'.($style?'<w:pStyle w:val="'.x($style).'"/>':'').'<w:spacing w:before="'.$before.'" w:after="'.$after.'" w:line="276" w:lineRule="auto"/><w:jc w:val="'.$align.'"/></w:pPr>';return '<w:p>'.$ppr.runText($text,$bold,$size).'</w:p>';}
function cell($text,$header=false,$width=3000){$fill=$header?'<w:shd w:val="clear" w:color="auto" w:fill="D9E2F3"/>':'';$pr='<w:tcPr><w:tcW w:w="'.$width.'" w:type="dxa"/>'.$fill.'<w:vAlign w:val="center"/></w:tcPr>';return '<w:tc>'.$pr.para($text,['align'=>$header?'center':'left','bold'=>$header,'size'=>20,'after'=>40]).'</w:tc>';}
function tbl($rows,$widths,$heights=[]){$xml='<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="5" w:color="666666"/><w:left w:val="single" w:sz="5" w:color="666666"/><w:bottom w:val="single" w:sz="5" w:color="666666"/><w:right w:val="single" w:sz="5" w:color="666666"/><w:insideH w:val="single" w:sz="4" w:color="999999"/><w:insideV w:val="single" w:sz="4" w:color="999999"/></w:tblBorders></w:tblPr><w:tblGrid>';foreach($widths as $wd)$xml.='<w:gridCol w:w="'.(int)$wd.'"/>';$xml.='</w:tblGrid>';foreach($rows as $ri=>$row){$xml.='<w:tr>'.(isset($heights[$ri])?'<w:trPr><w:trHeight w:val="'.(int)$heights[$ri].'" w:hRule="atLeast"/></w:trPr>':'');foreach(array_values($row) as $ci=>$v)$xml.=cell($v,$ri===0,$widths[$ci]??2500);$xml.='</w:tr>';}$xml.='</w:tbl>';return $xml;}
function pageBreak(){return '<w:p><w:r><w:br w:type="page"/></w:r></w:p>'; }
