$filename=preg_replace('/[^A-Za-z0-9._-]+/','_',($r['kak_no'].'_'.$r['title'])).'.docx';while(ob_get_level())ob_end_clean();header('Content-Type: application/vnd.openxmlformats-officedocument.wordprocessingml.document');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.filesize($outPath));readfile($outPath);@unlink($outPath);exit;
